private void xrLabel28_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            double shuma = 0;
            for (int i = 0; i < e.CalculatedValues.Count; i++)
            {
                string shumaFormatuar = (Convert.ToDouble(e.CalculatedValues[i])).ToString("N2");
                shuma += double.Parse(shumaFormatuar);
            }
            if (shuma >= 0)
                e.Result = shuma;
            else
                e.Result = 0.00;
            e.Handled = true;
}

